//! Shared daemon adapter. Per-account fails closed until the shell can supply
//! authenticated OS isolation; different working directories are not a sandbox.
mod client;
mod process;
pub mod protocol;
mod routes;
mod sessions;
mod input;
#[cfg(test)] mod extension_tests;
mod supervisor;
mod translate;
#[cfg(windows)] mod windows_job;
#[cfg(test)] mod tests;
use super::*;
use client::{Client, Control};
use protocol::{Command, Empty, Prompt};
use parking_lot::Mutex;
use std::{collections::HashSet, sync::mpsc};
use serde_json::Value;

pub struct PiBackend {
    config: config::Agentd,
    client: once_cell::sync::OnceCell<Arc<Client>>,
    preparing: Arc<Mutex<HashSet<String>>>,
    cancelled: Arc<Mutex<HashSet<String>>>,
    provider_config: Mutex<Option<(Option<u32>, Value)>>,
}
impl PiBackend {
    pub fn new(config: config::Agentd) -> anyhow::Result<Self> {
        config::Config { agent: config::Agent::default(), agentd: config.clone() }.validate()?;
#[serde(rename_all = "camelCase")]
pub struct Ping {
    pub status: String, pub sessions: u64, pub version: String,
    pub pi_version: String, pub protocol_version: u64, pub usage_persist_failures: u64,
}
pub fn check_ping(value: Value) -> anyhow::Result<Ping> {
    anyhow::ensure!(value.get("protocolVersion").and_then(Value::as_u64) == Some(PROTOCOL_VERSION),
        "AgentdProtocolMismatch: expected protocolVersion={PROTOCOL_VERSION}");
    let ping: Ping = serde_json::from_value(value)?;
    anyhow::ensure!(ping.status == "ok" && !ping.version.is_empty() && !ping.pi_version.is_empty(), "AgentdPingFailed");
    Ok(ping)
}
#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Text { pub session_id: String, pub text: String }
#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Session { pub session_id: String }
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Apply {
    #[serde(skip_serializing_if = "Option::is_none")] pub config: Option<Value>,
    #[serde(skip_serializing_if = "Option::is_none")] pub credentials: Option<Value>,
}
#[derive(Debug, Clone, Deserialize)]
pub struct WireError { pub code: String, pub message: String, pub paths: Option<Vec<String>> }
#[derive(Debug, Deserialize)]
#[serde(tag = "type")]
pub enum Frame {
    #[serde(rename = "response")]
    Response { id: Option<Id>, ok: bool, result: Option<Value>, error: Option<WireError> },
    #[serde(rename = "event", rename_all = "camelCase")]
    Event { session_id: String, turn_id: String, #[serde(flatten)] event: Event },
}
#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum PermissionResolution { Responded, Expired, Cancelled }
#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "event")]
pub enum Event {
    #[serde(rename = "permission.request", rename_all = "camelCase")]
    PermissionRequest { target_session_id: String, call_id: String, tool: String, summary: String, expires_at: u64, parent_call_id: Option<String> },
    #[serde(rename = "permission.resolved", rename_all = "camelCase")]
        .map(|l| l.trim())
        .find(|l| !l.is_empty())
        .map(|s| s.to_string())
}

/// 路径归一 (小写 + 去尾斜杠), 用于去重 / 比对。
fn norm(p: &Path) -> String {
    p.to_string_lossy()
        .trim_end_matches(['\\', '/'])
        .to_lowercase()
}

/// 由一个 claude 可执行文件推出它所属的「安装根」——
/// npm 装的 `<prefix>/node_modules/@anthropic-ai/claude-code/bin/claude.exe` 与
/// `<prefix>/claude.cmd` 是**同一份安装的两个入口**, 必须归成一类, 否则一份安装会被
/// 误报成两份冲突。其余情况取父目录。
fn install_root(p: &Path) -> PathBuf {
    let comps: Vec<_> = p.components().collect();
    if let Some(i) = comps.iter().position(|c| c.as_os_str() == "node_modules") {
        return comps[..i].iter().collect();
    }
    p.parent().map(|x| x.to_path_buf()).unwrap_or_default()
}

/// 给安装根起个人话名字 (面板里比一长串路径好认)。
